public class JSTypeRegistry_canPropertyBeDefined_TriageGen0Test {

    private JSTypeRegistry registry;
    private ErrorReporter errorReporter;

    @Before
    public void setUp() {
        errorReporter = mock(ErrorReporter.class);
        registry = new JSTypeRegistry(errorReporter);
    }

    /**
     * Tests the case where the property name does not exist in the registry at all.
     * Covers the first 'if' branch returning false.
     */
    @Test
    public void testCanPropertyBeDefined_PropertyNotFound() {
        JSType type = registry.getNativeObjectType(JSTypeNative.OBJECT);
        assertFalse(registry.canPropertyBeDefined(type, "nonExistentProperty"));
    }

    /**
     * Tests the case where the property exists, but all associated types 
     * result in an empty subtype when checked against the target type.
     * Covers the loop completing without returning true.
     */
    @Test
    public void testCanPropertyBeDefined_PropertyExistsButNoValidSubtype() {
        String prop = "myProp";
        JSType targetType = registry.getNativeObjectType(JSTypeNative.STRING);

        // Create a mock type that will be indexed by the property
        JSType mockAltType = mock(JSType.class);
        JSType emptyType = mock(JSType.class);

        // Setup: mockAltType.getGreatestSubtype(targetType) returns an empty type
        when(mockAltType.getGreatestSubtype(targetType)).thenReturn(emptyType);
        when(emptyType.isEmptyType()).thenReturn(true);

        // We need to simulate the internal 'typesIndexedByProperty' structure.
        // Since we can't access the private map directly, we use the public API 
        // registerPropertyOnType to populate the registry.
        // Note: registerPropertyOnType usually expects a valid JSType.
        registry.registerPropertyOnType(prop, mockAltType);

        assertFalse(registry.canPropertyBeDefined(targetType, prop));
    }

    /**
     * Tests the case where the property exists and the greatest subtype is NOT empty.
     * Covers the 'if (!greatestSubtype.isEmptyType())' branch returning true.
     */
    @Test
    public void testCanPropertyBeDefined_PropertyExistsAndValidSubtypeFound() {
        String prop = "myProp";
        JSType targetType = registry.getNativeObjectType(JSTypeNative.OBJECT);

        // Create mock types
        JSType mockAltType = mock(JSType.class);
        JSType validSubtype = mock(JSType.class);

        // Setup: mockAltType.getGreatestSubtype(targetType) returns a non-empty type
        when(mockAltType.getGreatestSubtype(targetType)).thenReturn(validSubtype);
        when(validSubtype.isEmptyType()).thenReturn(false);

        // Register the property
        registry.registerPropertyOnType(prop, mockAltType);

        assertTrue(registry.canPropertyBeDefined(targetType, prop));
    }

    /**
     * Tests the case where a property name maps to a union type (multiple alternates).
     * This ensures the loop correctly iterates through alternates.
     */
    @Test
    public void testCanPropertyBeDefined_MultipleAlternatesOneValid() {
        String prop = "unionProp";
        JSType targetType = registry.getNativeObjectType(JSTypeNative.OBJECT);

        // We use a real UnionType via the registry to ensure getAlternates() works correctly
        JSType typeA = registry.getNativeObjectType(JSTypeNative.STRING);
        JSType typeB = registry.getNativeObjectType(JSTypeNative.NUMBER);
        JSType unionType = registry.createUnionType(typeA, typeB);

        // Register the union type for the property
        registry.registerPropertyOnType(prop, unionType);

        // targetType is OBJECT. 
        // For STRING and NUMBER, greatestSubtype of OBJECT is usually themselves or empty 
        // depending on implementation, but we want to ensure the loop logic is hit.
        // Since we registered a real union, we test if it finds a valid subtype.

        // If targetType is OBJECT, and union contains STRING/NUMBER, 
        // getGreatestSubtype(OBJECT) should return the union or parts of it.
        assertTrue(registry.canPropertyBeDefined(targetType, prop));
    }
}
